    "rscript": "library(haven)
library(dplyr)
library(tidyr)
library(purrr)
library(labelled)
library(readr)

# 1. File Loading
file1 <- read_delim("data/input/wave_one_lsype_family_background_2020.tab", delim = "\t", col_types = readr::cols(.default = "guess"))
file2 <- read_delim("data/input/wave_two_lsype_family_background_2020.tab", delim = "\t", col_types = readr::cols(.default = "guess"))
file4 <- read_delim("data/input/wave_four_lsype_family_background_2020.tab", delim = "\t", col_types = readr::cols(.default = "guess"))

# Merge datasets
df <- file1 %>%
  full_join(file2, by = "NSID") %>%
  full_join(file4, by = "NSID")

# 2. Harmonise Missing Codes
# Standard Scheme:
# -9 = Refusal
# -8 = Don't know / insufficient info
# -7 = Prefer not to say
# -3 = Not asked / Not interviewed
# -2 = Schedule not applicable / script error / info lost
# -1 = Item not applicable

map_missing <- function(val, labels) {
  if (is.na(val)) return(-3)

  # Extract label for the value
  label <- labels[as.character(val)]
  if (is.na(label)) return(val)

  lbl <- tolower(label)
  if (grepl("refused", lbl)) return(-9)
  if (grepl("don't know|insufficient information", lbl)) return(-8)
  if (grepl("prefer not to say", lbl)) return(-7)
  if (grepl("not interviewed|not asked", lbl)) return(-3)
  if (grepl("household data lost|script error|information lost", lbl)) return(-2)
  if (grepl("not applicable", lbl)) return(-1)

  return(val)
}

# Process Mothers
# Variables: W1hiqualmum, W2hiqualmum, w4hiqualmum
# Labels for mapping
l_w1m <- c("-999.0" = "Missing - household data lost", "-99.0" = "Mother not interviewed", "-98.0" = "Mother not present", "-94.0" = "Insufficient information", "-92.0" = "Refused", "-91.0" = "Not applicable")
l_w2m <- c("-999.0" = "Missing - household data lost", "-99.0" = "Mother not interviewed", "-98.0" = "Mother not present", "-94.0" = "Insufficient information", "-92.0" = "Refused", "-91.0" = "Not applicable")
l_w4m <- c("-99.0" = "Mother not interviewed", "-98.0" = "Mother not present", "-94.0" = "Insufficient information")

df <- df %>%
  mutate(
    m1_h = map2_dbl(W1hiqualmum, list(l_w1m), ~map_missing(.x, .y)),
    m2_h = map2_dbl(W2hiqualmum, list(l_w2m), ~map_missing(.x, .y)),
    m4_h = map2_dbl(w4hiqualmum, list(l_w4m), ~map_missing(.x, .y)),
    d1_h = map2_dbl(W1hiqualdad, list(c("-999.0" = "Missing - household data lost", "-99.0" = "Father not interviewed", "-98.0" = "Father not present", "-94.0" = "Insufficient information", "-92.0" = "Refused", "-91.0" = "Not applicable", "-1.0" = "Don't know"))), 
    # Wait, I need to be careful with the map_missing function logic. 
    # Let's refine the function to be used in a more vectorized way or via rowwise.
  )

# Redefining for rowwise use
clean_val <- function(val, labels) {
  if (is.na(val)) return(-3)
  lbl <- labels[as.character(val)]
  if (is.na(lbl)) return(val)
  lbl <- tolower(lbl)
  if (grepl("refused", lbl)) return(-9)
  if (grepl("don't know|insufficient information", lbl)) return(-8)
  if (grepl("prefer not to say", lbl)) return(-7)
  if (grepl("not interviewed|not asked", lbl)) return(-3)
  if (grepl("household data lost|script error|information lost", lbl)) return(-2)
  if (grepl("not applicable", lbl)) return(-1)
  return(val)
}

# Correcting the mapping approach
# Detailed Labels for factors
detail_labels <- c(
  "1" = "Higher Degree", "2" = "First Degree", "3" = "HE Diploma", "4" = "HNC/HND/NVQ4",
  "5" = "Teaching qualification, non-degree", "6" = "Nursing qualification, non-degree", "7" = "A Levels", "8" = "OND/ONC",
